const subsidy = Number(get(facts, 'statutory.NHI.disability_subsidy', 0)) / 100;
const own = round(insured * ctx.lookup.rate * ctx.lookup.employee_share, 1, 'HALF_UP');
return round(own * (1 - subsidy) + own * dependants, 1, 'HALF_UP');

