employee_amount:
// 全民健康保險法 §31(1)(1); 扣取及繳納補充保險費辦法 §4, §6: 2.11% on the part of this bonus that takes the year's bonuses past four times the insured amount, at most NT$10,000,000 a payment. §9: what was over-deducted goes back, so a reversal owes what the year's bonuses leave less what they bore.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
const wage = get(employment, 'terms.rate.unit', 'MONTHLY') === 'MONTHLY'
  ? round(ctx.month_wage, 0.01)
  : Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const grade = ctx.lookup.nhi_grades.find((row) => row >= wage) ?? ctx.lookup.nhi_grades.at(-1);
const insured = Number(get(facts, 'statutory.NHI.insured_amount', grade));
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
const paid = Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)) - Number(get(ctx.balances, 'ytd.ORDINARY_WAGES', 0));
if (bonus < 0) {
  const schemes = get(ctx.balances, 'statutory_contribution', {});
  const bore = Object.hasOwn(schemes, 'NHI_SUPPLEMENT.employee') ? Number(schemes['NHI_SUPPLEMENT.employee']) : 0;
  const left = Math.max(0, paid + bonus - ctx.lookup.bonus_salary_multiple * insured);
  return Math.min(0, round(left * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP') - bore);
}
const excess = Math.max(0, paid + bonus - ctx.lookup.bonus_salary_multiple * insured);
return round(Math.min(excess, bonus, ctx.lookup.nhi_supplement_payment_ceiling) * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP');

// 全民健康保險法 §31(1)(2): 2.11% on a salary payment to a worker insured elsewhere, charged whole from the minimum wage. SALARY_INCOME holds no exempt meal or §32 overtime (所得稅法 §14(1)(3)).
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
if (get(facts, 'statutory.NHI.insured_elsewhere', false) !== true) return 0;
if (get(facts, 'statutory.NHI_PART_TIME.exempt', false) === true) return 0;
const payment = get(ctx.subtotals, 'SALARY_INCOME', 0);
if (!(payment >= ctx.lookup.monthly_wage)) return 0;
return round(Math.min(payment, ctx.lookup.nhi_supplement_payment_ceiling) * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP');

